package com.csust.eyediagnosis.workflow.graph.runtime;
import com.csust.eyediagnosis.workflow.evidence.*; import com.csust.eyediagnosis.workflow.persistence.entity.DiagnosisCitationEntity; import com.csust.eyediagnosis.workflow.persistence.repository.DiagnosisCitationRepository; import org.junit.jupiter.api.Test; import java.util.HashMap; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*;
class EvidenceCitationDeltaWriterTest { @Test void insertsOnceAndNeverProvidesMutationPath() { HashMap<String, DiagnosisCitationEntity> rows = new HashMap<>(); DiagnosisCitationRepository repository = new DiagnosisCitationRepository() { public int insert(DiagnosisCitationEntity entity) { rows.put(entity.getWorkflowId() + entity.getQuotedSpanDigest(), entity); return 1; } public Optional<DiagnosisCitationEntity> findByBusinessKey(String workflow, long epoch, String source, String revision, String digest) { return Optional.ofNullable(rows.get(workflow + digest)); } }; DiagnosisCitationSnapshot citation = new DiagnosisCitationSnapshot("wf", 3, "source", "r1", "chunk", "title", "quote", "digest", java.util.Set.of("amd"), java.util.Set.of("DISEASE_OVERVIEW"), .5, "governed-vector-v1", "evidence-term-catalog-v1"); EvidenceSufficiency sufficiency = new EvidenceSufficiency(1, java.util.Set.of("amd"), java.util.Set.of("DISEASE_OVERVIEW"), true, EvidenceSufficiencyReasonCode.SUFFICIENT); EvidenceCitationDeltaWriter writer = new EvidenceCitationDeltaWriter(repository); writer.write(new EvidenceCitationDelta(3, java.util.List.of(citation), sufficiency)); writer.write(new EvidenceCitationDelta(3, java.util.List.of(citation), sufficiency)); assertEquals(1, rows.size()); } }
